const sc = $('Scope Config').all();
const cfg = sc[0].json;
const out = [], errors = [];
const DAY = 86400000;
const toMs = s => { if (!s) return null; const t = Date.parse(/[zZ]|[+-]\d\d:?\d\d$/.test(s) ? s : s + 'Z'); return isNaN(t) ? null : t; };

const crtAll = (() => { try { return $('crt.sh Discovery').all(); } catch (e) { return []; } })();
const warnings = [];
const parse = (item) => { try { const raw = item && item.json ? item.json.data : ''; if (typeof raw !== 'string' || !raw.trim().startsWith('[')) return null; const r = JSON.parse(raw); return Array.isArray(r) ? r : null; } catch (e) { return null; } };

$input.all().forEach((it, i) => {
  const domain = sc[i].json.domain;
  const crtRows = parse(crtAll[i]), csRows = parse(it);
  if (!crtRows && !csRows) { errors.push({ domain, error: 'discovery failed: crt.sh and CertSpotter both unavailable (try again later)' }); return; }
  if (!crtRows) warnings.push({ domain, warning: 'crt.sh unavailable - used CertSpotter only (may be incomplete)' });
  const rows = crtRows ? crtRows.slice() : [];
  if (csRows) csRows.forEach(r => rows.push({ name_value: (r.dns_names || []).join('\n'), not_after: r.not_after, not_before: r.not_before, issuer_name: (r.issuer && (r.issuer.name || r.issuer.friendly_name)) || '' }));
  const exact = {}, wild = {};
  for (const row of rows) {
    const na = toMs(row.not_after), nb = toMs(row.not_before);
    for (let name of String(row.name_value || '').split('\n')) {
      name = name.trim().toLowerCase();
      if (!name) continue;
      const isWild = name.startsWith('*.');
      if (isWild) name = name.slice(2);
      if (!/^[a-z0-9.-]+$/.test(name)) continue;
      if (name !== domain && !name.endsWith('.' + domain)) continue;
      const bucket = isWild ? wild : exact;
      if (!bucket[name] || (na || 0) > (bucket[name].na || 0)) bucket[name] = { na, nb, issuer: row.issuer_name || '' };
    }
  }
  const excluded = new Set((cfg.excluded_hosts || []).map(x => x.toLowerCase()));
  const hosts = Object.keys(exact).filter(h => !excluded.has(h)).sort().slice(0, cfg.max_hosts_per_domain || 150);
  for (const host of hosts) {
    const parent = host.split('.').slice(1).join('.');
    const c = exact[host];
    const w = wild[parent];
    const best = (w && (w.na || 0) > (c.na || 0)) ? { ...w, src: 'wildcard' } : { ...c, src: 'exact' };
    out.push({ json: { domain, host, cert_not_after: best.na ? new Date(best.na).toISOString() : null, cert_issuer: best.issuer, cert_source: best.src } });
  }
});
if (!out.length) return [{ json: { __none: true, errors, discovery_warnings: warnings } }];
out[0].json.discovery_errors = errors;
out[0].json.discovery_warnings = warnings;
return out;

const ex = $('Extract Subdomains').all();
return $input.all().map((it, i) => {
  const base = ex[i].json, r = it.json || {};
  const ans = Array.isArray(r.Answer) ? r.Answer : [];
  const ips = ans.filter(a => a.type === 1).map(a => a.data);
  const cnames = ans.filter(a => a.type === 5).map(a => String(a.data).toLowerCase().replace(/\.$/, ''));
  return { json: { ...base, dns_status: typeof r.Status === 'number' ? r.Status : -1, ips, cnames, resolves: ips.length > 0 } };
});

const safeAll = n => { try { return $(n).all(); } catch (e) { return []; } };
const sd = $getWorkflowStaticData('global');
sd.asm = sd.asm || { inventory: {}, findings: {}, baselined: {}, last_run: null };
const A = sd.asm;
const cfg = (safeAll('Scope Config')[0] || { json: {} }).json;
const domains = safeAll('Scope Config').map(x => x.json.domain);
const now = Date.now(), DAY = 86400000, nowIso = new Date().toISOString();
const SCORE = { CRITICAL: 90, HIGH: 75, MEDIUM: 50, LOW: 20, INFO: 5 };
const RANK = { CRITICAL: 4, HIGH: 3, MEDIUM: 2, LOW: 1, INFO: 0 };

const ex = safeAll('Extract Subdomains'), dns = safeAll('Merge DNS'), idb = safeAll('Shodan InternetDB'), probe = safeAll('Probe HTTPS');
const discErrors = ex[0]?.json ? (ex[0].json.discovery_errors || ex[0].json.errors || []) : [];
const discWarn = ex[0] && ex[0].json ? (ex[0].json.discovery_warnings || []) : [];
const failedDomains = new Set(discErrors.map(e => e.domain));
const kev = new Set();
// Replaced CISA KEV Feed with Neo4j
try { (safeAll('Neo4j Read Vulns').map(v => v.json)).forEach(v => kev.add(v.cve)); } catch (e) {}

const TAKEOVER = [/github\.io$/, /herokuapp\.com$/, /herokudns\.com$/, /azurewebsites\.net$/, /cloudapp\.azure\.com$/, /trafficmanager\.net$/, /blob\.core\.windows\.net$/, /s3[.-][a-z0-9.-]*amazonaws\.com$/, /elasticbeanstalk\.com$/, /cloudfront\.net$/, /netlify\.app$/, /vercel\.app$/, /surge\.sh$/, /ghost\.io$/, /zendesk\.com$/, /readme\.io$/, /pantheonsite\.io$/, /myshopify\.com$/, /bitbucket\.io$/];
const TAKEOVER_FP = /(there isn't a github pages site here|no such app|nosuchbucket|the specified bucket does not exist|repository not found|project not found|no settings were found for this company|the thing you were looking for is no longer here|fastly error: unknown domain)/i;
const ADMIN = [[/jenkins/i, 'Jenkins', 'HIGH'], [/grafana/i, 'Grafana', 'HIGH'], [/kibana/i, 'Kibana', 'HIGH'], [/phpmyadmin/i, 'phpMyAdmin', 'HIGH'], [/adminer/i, 'Adminer', 'HIGH'], [/sonarqube/i, 'SonarQube', 'HIGH'], [/traefik/i, 'Traefik dashboard', 'HIGH'], [/kubernetes dashboard/i, 'Kubernetes Dashboard', 'CRITICAL'], [/portainer/i, 'Portainer', 'HIGH'], [/argo cd/i, 'Argo CD', 'HIGH'], [/rabbitmq management/i, 'RabbitMQ Management', 'HIGH'], [/airflow/i, 'Airflow', 'HIGH'], [/swagger ui/i, 'Swagger UI', 'MEDIUM'], [/^index of \//i, 'Directory listing', 'MEDIUM']];
const PORTS = { 23: ['Telnet', 'HIGH'], 3389: ['RDP', 'HIGH'], 5900: ['VNC', 'HIGH'], 22: ['SSH', 'MEDIUM'], 21: ['FTP', 'MEDIUM'], 445: ['SMB', 'HIGH'], 1433: ['MSSQL', 'HIGH'], 3306: ['MySQL', 'HIGH'], 5432: ['PostgreSQL', 'HIGH'], 6379: ['Redis', 'CRITICAL'], 27017: ['MongoDB', 'CRITICAL'], 9200: ['Elasticsearch', 'CRITICAL'], 11211: ['Memcached', 'CRITICAL'], 2375: ['Docker API', 'CRITICAL'], 5984: ['CouchDB', 'HIGH'], 9092: ['Kafka', 'HIGH'], 2181: ['ZooKeeper', 'HIGH'] };

const current = [];
const F = (host, domain, code, sev, title, evidence, fix, detail = '') => current.push({ key: `${code}|${host}|${detail}`, code, host, domain, severity: sev, score: SCORE[sev], title, evidence, fix });

const assets = [], scannedHosts = new Set();
dns.forEach((d, i) => {
  const b = d.json, p = (probe[i] && probe[i].json) || {}, db = (idb[i] && idb[i].json) || {};
  const host = b.host; scannedHosts.add(host);
  const status = typeof p.statusCode === 'number' ? p.statusCode : null;
  const live = status !== null;
  const body = typeof p.body === 'string' ? p.body.slice(0, 60000) : '';
  const headers = {}; Object.entries(p.headers || {}).forEach(([k, v]) => headers[k.toLowerCase()] = String(v));
  const title = ((body.match(/<title[^>]*>([\s\S]{0,300}?)<\/title>/i) || [])[1] || '').replace(/\s+/g, ' ').replace(/[^\x20-\x7E]/g, '').trim().slice(0, 120);
  const ports = Array.isArray(db.ports) ? db.ports : [];
  const vulns = Array.isArray(db.vulns) ? db.vulns : [];
  const owner = ((cfg.owners || []).find(o => { try { return new RegExp(o.pattern).test(host); } catch (e) { return false; } }) || {}).owner || 'unknown';
  const days = b.cert_not_after ? Math.floor((Date.parse(b.cert_not_after) - now) / DAY) : null;
  const a = { host, domain: b.domain, ips: b.ips, cnames: b.cnames, resolves: b.resolves, live, http_status: status, title, server: headers['server'] || '', ports, vulns, cert_not_after: b.cert_not_after, cert_days_left: days, cert_issuer: b.cert_issuer, owner };
  assets.push(a);

  // --- subdomain takeover ---
  const prov = b.cnames.find(c => TAKEOVER.some(re => re.test(c)));
  if (prov && (b.dns_status === 3 || !b.resolves || TAKEOVER_FP.test(body)))
    F(host, b.domain, 'SUBDOMAIN_TAKEOVER', 'HIGH', 'Possible subdomain takeover (dangling CNAME)', `CNAME -> ${prov}; ${b.dns_status === 3 ? 'NXDOMAIN' : b.resolves ? 'provider "not found" page' : 'no A record'}`, 'Remove the DNS record or re-claim the resource at the provider.');
  // --- certificates (from Certificate Transparency logs) ---
  if (days !== null && live) {
    if (days < 0) F(host, b.domain, 'CERT_EXPIRED', 'HIGH', 'Latest known certificate has expired', `expired ${-days} day(s) ago (CT log, ${b.cert_source})`, 'Renew the certificate and enable auto-renewal.');
    else if (days <= 7) F(host, b.domain, 'CERT_EXPIRING', 'HIGH', 'Certificate expires within 7 days', `${days} day(s) left`, 'Renew now.');
    else if (days <= 14) F(host, b.domain, 'CERT_EXPIRING', 'MEDIUM', 'Certificate expires within 14 days', `${days} day(s) left`, 'Renew soon.');
    else if (days <= (cfg.cert_warn_days || 30)) F(host, b.domain, 'CERT_EXPIRING', 'LOW', 'Certificate expires within 30 days', `${days} day(s) left`, 'Schedule renewal.');
  }
  // --- exposed admin panels / listings ---
  if (live && status === 200) {
    const hay = `${title} ${headers['x-jenkins'] ? 'jenkins' : ''} ${headers['x-grafana-version'] ? 'grafana' : ''}`;
    for (const [re, name, sev] of ADMIN) if (re.test(hay)) { F(host, b.domain, 'EXPOSED_ADMIN', sev, `${name} reachable from the internet`, `HTTP 200, title "${title}"`, 'Restrict to VPN/SSO or an IP allow-list.', name); break; }
    if (!headers['strict-transport-security']) F(host, b.domain, 'NO_HSTS', 'LOW', 'HSTS header missing', 'No Strict-Transport-Security header', 'Add HSTS to HTTPS responses.');
  }
  // --- risky open ports (Shodan InternetDB) ---
  for (const port of ports) if (PORTS[port]) F(host, b.domain, 'RISKY_PORT', PORTS[port][1], `${PORTS[port][0]} (${port}) exposed to the internet`, `Shodan InternetDB lists port ${port} on ${(b.ips || [])[0]}`, 'Close the port or restrict the firewall / security group to trusted IPs.', String(port));
  // --- known vulnerabilities (version-based, unverified) ---
  const kevHits = vulns.filter(v => kev.has(v));
  if (kevHits.length) F(host, b.domain, 'KEV_CVE', 'CRITICAL', 'Matches CVE(s) actively exploited in the wild (CISA KEV)', kevHits.slice(0, 5).join(', '), 'Patch immediately; verify the finding on the host.', kevHits.slice(0, 5).join(','));
  else if (vulns.length) F(host, b.domain, 'POSSIBLE_CVE', 'MEDIUM', 'Possible known vulnerabilities (version-based, unverified)', `${vulns.length} CVE(s), e.g. ${vulns.slice(0, 3).join(', ')}`, 'Verify the installed versions and patch.', 'cves');
});

// --- email posture per root domain ---
const dm = safeAll('DMARC Lookup'), sp = safeAll('SPF Lookup');
const txt = r => (((r && r.json && r.json.Answer) || []).filter(x => x.type === 16).map(x => String(x.data).replace(/^"|"$/g, '').replace(/"\s*"/g, '')));
domains.forEach((dom, i) => {
  if (failedDomains.has(dom)) return;
  const dmarc = txt(dm[i]).find(t => /^v=DMARC1/i.test(t)), spf = txt(sp[i]).find(t => /^v=spf1/i.test(t));
  if (!dmarc) F(dom, dom, 'NO_DMARC', 'MEDIUM', 'No DMARC record', `_dmarc.${dom} has no DMARC policy`, 'Publish a DMARC policy and move to p=quarantine/reject.');
  else if (/p=none/i.test(dmarc)) F(dom, dom, 'DMARC_MONITOR_ONLY', 'LOW', 'DMARC policy is p=none', dmarc.slice(0, 120), 'Move to p=quarantine or p=reject.');
  if (!spf) F(dom, dom, 'NO_SPF', 'MEDIUM', 'No SPF record', `${dom} has no SPF record`, 'Publish an SPF record.');
  else if (/\+all\b/.test(spf)) F(dom, dom, 'SPF_PERMISSIVE', 'HIGH', 'SPF allows any sender (+all)', spf.slice(0, 120), 'Use -all or ~all.');
});

// --- diff against previous inventory ---
const changes = { new_hosts: [], went_dark: [], new_ports: [], newly_live: [] };
const baselineCreated = [];
for (const a of assets) {
  const prev = A.inventory[a.host], baselined = A.baselined[a.domain];
  if (!prev) { if (baselined) changes.new_hosts.push(a.host); }
  else {
    if (prev.live && !a.live && !a.resolves) changes.went_dark.push(a.host);
    if (!prev.live && a.live) changes.newly_live.push(a.host);
    const added = (a.ports || []).filter(p => !(prev.ports || []).includes(p));
    if (added.length) changes.new_ports.push(`${a.host}:${added.join(',')}`);
  }
  A.inventory[a.host] = { ...a, first_seen: prev ? prev.first_seen : nowIso, last_seen: nowIso };
}
for (const dom of domains) if (!failedDomains.has(dom) && !A.baselined[dom] && assets.some(a => a.domain === dom)) { A.baselined[dom] = nowIso; baselineCreated.push(dom); }
const invKeys = Object.keys(A.inventory); if (invKeys.length > 3000) invKeys.slice(0, invKeys.length - 3000).forEach(k => delete A.inventory[k]);
for (const h of changes.new_hosts) { const a = A.inventory[h]; if (a && a.live) F(h, a.domain, 'NEW_SUBDOMAIN', 'LOW', 'New live subdomain appeared', `owner: ${a.owner}`, 'Confirm it is expected and assign an owner.'); }

// --- finding lifecycle: new / existing / resolved ---
const curKeys = new Set(), newFindings = [];
for (const f of current) {
  curKeys.add(f.key);
  const ex0 = A.findings[f.key];
  if (!ex0) { A.findings[f.key] = { ...f, first_seen: nowIso, last_seen: nowIso }; newFindings.push(A.findings[f.key]); }
  else A.findings[f.key] = { ...ex0, ...f, first_seen: ex0.first_seen, last_seen: nowIso };
}
let resolved = 0;
for (const [k, rec] of Object.entries(A.findings)) {
  if (curKeys.has(k) || failedDomains.has(rec.domain) || !domains.includes(rec.domain)) continue;
  if (scannedHosts.has(rec.host) || domains.includes(rec.host)) { delete A.findings[k]; resolved++; }
}
const open = Object.values(A.findings);
const count = s => open.filter(f => f.severity === s).length;
const invAll = Object.values(A.inventory);
const metrics = {
  total_assets: invAll.length, live_assets: invAll.filter(a => a.live).length,
  unowned_live_assets: invAll.filter(a => a.live && a.owner === 'unknown').length,
  open_findings: open.length, critical: count('CRITICAL'), high: count('HIGH'), medium: count('MEDIUM'), low: count('LOW'),
  certs_expiring_30d: open.filter(f => f.code === 'CERT_EXPIRING').length,
  exposed_admin_panels: open.filter(f => f.code === 'EXPOSED_ADMIN').length,
  takeover_risks: open.filter(f => f.code === 'SUBDOMAIN_TAKEOVER').length,
  new_findings: newFindings.length, resolved_findings: resolved
};
newFindings.sort((a, b) => b.score - a.score);
const manual = $execution.mode === 'test';
const alert_needed = manual || baselineCreated.length > 0 || discErrors.length > 0 || newFindings.some(f => RANK[f.severity] >= 2) || changes.new_hosts.length > 0 || changes.went_dark.length > 0 || changes.new_ports.length > 0;
A.last_run = { ts: nowIso, domains, hosts_scanned: scannedHosts.size, metrics, discovery_errors: discErrors };
const llm_input = JSON.stringify({ domains, baseline_created: baselineCreated, metrics, discovery_errors: discErrors.length,
  changes: { new_hosts: changes.new_hosts.length, went_dark: changes.went_dark.length, new_ports: changes.new_ports.length },
  top_new_findings: newFindings.slice(0, 15).map(f => ({ severity: f.severity, code: f.code, host: f.host })) });
return [{ json: { alert_needed, domains, baseline_created: baselineCreated, metrics, changes, discovery_errors: discErrors, new_findings: newFindings.slice(0, 40), discovery_warnings: discWarn, llm_input, hosts_scanned: scannedHosts.size } }];

const d = $('Analyze & Diff').first().json;
const j = $input.first().json || {};
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/[`*_~]/g, '');
const brief = typeof j.text === 'string' ? esc(j.text).slice(0, 1200) : '';
const E = { CRITICAL: '🔴', HIGH: '🟠', MEDIUM: '🟡', LOW: '🔵', INFO: '⚪' };
const m = d.metrics, c = d.changes;
let t = `🛰️ *Attack Surface Report* — ${esc(d.domains.join(', '))}\n`;
if (d.baseline_created.length) t += `📌 Baseline created for ${esc(d.baseline_created.join(', '))}: future runs will alert on *changes*.\n`;
t += `*Assets:* ${m.total_assets} (live ${m.live_assets}, unowned live ${m.unowned_live_assets}) | *Open findings:* ${m.critical} critical, ${m.high} high, ${m.medium} medium, ${m.low} low\n`;
t += `*This run:* ${m.new_findings} new, ${m.resolved_findings} resolved, ${d.hosts_scanned} hosts scanned\n`;
if (brief) t += `\n*AI briefing*\n${brief}\n`;
if (d.new_findings.length) { t += `\n*New findings*\n`; d.new_findings.slice(0, 12).forEach(f => { t += `${E[f.severity]} *${f.severity}* ${esc(f.host)} — ${esc(f.title)} (${esc(f.evidence)})\n`; }); if (d.new_findings.length > 12) t += `…and ${d.new_findings.length - 12} more\n`; }
const ch = [];
if (c.new_hosts.length) ch.push(`➕ new subdomains: ${c.new_hosts.slice(0, 8).map(esc).join(', ')}`);
if (c.went_dark.length) ch.push(`➖ went dark: ${c.went_dark.slice(0, 8).map(esc).join(', ')}`);
if (c.new_ports.length) ch.push(`🔌 new open ports: ${c.new_ports.slice(0, 8).map(esc).join(', ')}`);
if (ch.length) t += `\n*Changes*\n${ch.join('\n')}\n`;
if (d.discovery_errors.length) t += `\n⚠️ Discovery failed for: ${esc(d.discovery_errors.map(e => e.domain).join(', '))} (results for these domains are incomplete)\n`;
if ((d.discovery_warnings || []).length) t += `\nℹ️ ${esc(d.discovery_warnings.map(w => w.warning).filter((v, i, a) => a.indexOf(v) === i).join('; '))}\n`;
return [{ json: { text: t.slice(0, 3800) } }];

const A = ($getWorkflowStaticData('global')).asm || { inventory: {}, findings: {}, last_run: null };
const sev = { CRITICAL: 4, HIGH: 3, MEDIUM: 2, LOW: 1, INFO: 0 };
return [{ json: { last_run: A.last_run, assets: Object.values(A.inventory).sort((a, b) => a.host.localeCompare(b.host)), open_findings: Object.values(A.findings).sort((a, b) => sev[b.severity] - sev[a.severity] || b.score - a.score) } }];
